Record Producto
  Define nombre As String;
  Define precio, stock As Integer;
EndRecord

Function importe <- Importe(precio As Integer, cantidad As Integer)
  Define importe As Integer;
  importe <- precio * cantidad;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Function valido <- CodigoValido(codigo As Integer)
  Define valido As Boolean;
  valido <- codigo >= 1 And codigo <= 5;
EndFunction

Function texto <- InventarioJson(productos As Vector<Producto>)
  Define texto As String <- "{";
  For Each producto In productos Do
    If texto <> "{" Then
      texto <- texto + ", ";
    EndIf
    texto <- texto + '"' + producto.nombre + '": ' + toText(producto.stock);
  EndFor
  texto <- texto + "}";
EndFunction

Subroutine Catalogo() As Vector<Producto>
  Define productos As Vector<Producto> <- vector();
  productos.append(Producto("Jugo", 3, 10));
  productos.append(Producto("Sándwich", 5, 5));
  productos.append(Producto("Alfajor", 2, 8));
  productos.append(Producto("Agua", 1, 12));
  productos.append(Producto("Fruta", 2, 6));
  Return productos;
EndSubroutine

Algorithm Kiosco
  Define productos As Vector<Producto> <- Catalogo();
  Define total As Integer <- 0;
  Define codigo, cantidad As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read cantidad;
    If Not CodigoValido(codigo) Then
      Write "Código ", codigo, " no existe";
    Else
      If cantidad < 1 Then
        Write "Cantidad ", cantidad, " no válida";
      Else
        Define producto As Producto <- productos[codigo - 1];
        If cantidad > producto.stock Then
          Write producto.nombre, " x ", cantidad, " rechazado: quedan ", producto.stock;
        Else
          producto.stock <- producto.stock - cantidad;
          productos[codigo - 1] <- producto;
          Write producto.nombre, " x ", cantidad, " = ", Importe(producto.precio, cantidad);
          total <- total + Importe(producto.precio, cantidad);
        EndIf
      EndIf
    EndIf
    Read codigo;
  EndWhile
  Write "Total: ", total;
  Write "Con descuento: ", ConDescuento(total);
  Write "Inventario: ", InventarioJson(productos);
EndAlgorithm
